package vn.contractgovernance.api.notice;

import java.io.ByteArrayInputStream;
import java.sql.Timestamp;
import java.time.Clock;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import tools.jackson.databind.node.ObjectNode;
import vn.contractgovernance.api.shared.*;
import vn.contractgovernance.api.files.*;
import vn.contractgovernance.api.contract.AgreementRenderer;
import static vn.contractgovernance.api.change.ChangeService.id;

/** Single existing PDF claimant delegates here; dispatch is a separate durable local adapter. */
@Service
public class NoticeJobs {
 private final AuditService audit;private final NoticeService notices;private final EntityStore store;private final JsonSupport json;private final JobQueue queue;private final Clock clock;private final AgreementRenderer renderer;private final ClamAvScanner scanner;private final PrivateBlobStore blobs;private final GeneratedArtifactFiles files;private final TransactionTemplate tx;
 public NoticeJobs(NoticeService notices,EntityStore store,JsonSupport json,JobQueue queue,Clock clock,AgreementRenderer renderer,ClamAvScanner scanner,PrivateBlobStore blobs,GeneratedArtifactFiles files,PlatformTransactionManager manager,AuditService audit){this.audit=audit;this.notices=notices;this.store=store;this.json=json;this.queue=queue;this.clock=clock;this.renderer=renderer;this.scanner=scanner;this.blobs=blobs;this.files=files;tx=new TransactionTemplate(manager);}
 public void artifact(JobQueue.Job job){try{
  var n=store.require("Notice",job.targetId());var source=notices.source(n);notices.sourceIntegrity(n,source);
  if(!source.job().equals(job.id())||!source.hash().equals(job.expectedHash()))throw ApiException.of("STORAGE_INTEGRITY","PDF job source mismatch.");
  var bytes=renderer.render(source.body());var generated=notices.now();var scan=scanner.scan(bytes);if(scan.infected())throw ApiException.of("STORAGE_INTEGRITY","PDF scan rejected.");
  try(var pending=blobs.writePending(new ByteArrayInputStream(bytes))){tx.executeWithoutResult(status->{var current=notices.lock(n.id());if(!current.body().path("state").asString().equals("IN_REVIEW")||!current.body().path("artifactJobId").asString().equals(job.id().toString())){queue.cancel(job,"Notice PDF source obsolete");return;}notices.sourceIntegrity(current,source);if(!queue.succeed(job))return;
   var file=files.register(current,pending.stored(),scan,AgreementRenderer.VERSION,generated);store.jdbc().update("insert into cg_notice_artifact(source_id,file_id,source_hash,artifact_hash,created_at) values(?,?,?,?,?)",source.id(),file.id(),source.hash(),pending.stored().sha256(),Timestamp.from(clock.instant()));var body=(ObjectNode)current.body().deepCopy();body.put("artifactId",file.id().toString()).put("artifactHash",pending.stored().sha256());notices.save(current,body,null,"ARTIFACT_PDF",null);store.jdbc().update("update cg_job set result_file_id=? where id=?",file.id(),job.id());});}
 }catch(Exception failure){tx.executeWithoutResult(status->{var n=notices.lock(job.targetId());if(!n.body().path("state").asString().equals("IN_REVIEW")||!n.body().path("artifactJobId").asString().equals(job.id().toString()))queue.cancel(job,"Notice source obsolete");else queue.fail(job,failure instanceof ApiException a&&a.code().equals("STORAGE_INTEGRITY")?"STORAGE_INTEGRITY":"SCANNER_UNAVAILABLE","Notice render/storage/scan unavailable");});}}
 @Scheduled(fixedDelayString="${cg.notice.poll-ms:1500}")public void poll(){reconcile();var next=queue.claimForKind("NOTICE_DISPATCH",UUID.randomUUID());next.ifPresent(this::dispatch);}
 private void reconcile(){var ids=store.jdbc().query("select n.id from cg_entity n join cg_job j on j.id=(n.body->>'jobId')::uuid where n.entity_type='Notice' and n.body->>'state'='QUEUED' and j.kind='NOTICE_DISPATCH' and j.state='FAILED' order by n.id limit 100",(rs,i)->rs.getObject(1,UUID.class));for(var id:ids)tx.executeWithoutResult(status->{var n=notices.lock(id);var job=store.lock("Job",id(n.body(),"jobId"));if(n.body().path("state").asString().equals("QUEUED")&&job.body().path("state").asString().equals("FAILED")){var b=(ObjectNode)n.body().deepCopy();b.put("state","FAILED");notices.save(n,b,null,"DISPATCH_FAILED","Durable attempts exhausted");}});}
 private void dispatch(JobQueue.Job job){try{tx.executeWithoutResult(status->{var n=notices.lock(job.targetId());if(!n.body().path("state").asString().equals("QUEUED")||!n.body().path("jobId").asString().equals(job.id().toString())||!n.body().path("transport").asString().equals("LOCAL_CAPTURE")){queue.cancel(job,"Notice source obsolete");return;}
  notices.dependency(n);notices.artifactFile(n,null);notices.requireDispatchSource(n,job.id());var source=notices.source(n);if(!job.expectedHash().equals(json.hash(job.payload()))||!job.payload().path("sourceId").asString().equals(source.id().toString())||!job.payload().path("sourceHash").asString().equals(source.hash())||!job.payload().path("messageId").equals(n.body().path("messageId"))||!job.payload().path("artifactHash").equals(n.body().path("artifactHash")))throw ApiException.of("STORAGE_INTEGRITY","Dispatch source mismatch.");
  if(!queue.succeed(job))return;var capture=json.object().put("noticeId",n.id().toString()).put("messageId",n.body().path("messageId").asString()).put("subject",n.body().path("subject").asString()).put("bodyText",n.body().path("bodyText").asString()).put("artifactHash",n.body().path("artifactHash").asString()).put("acceptedAt",notices.now());capture.set("recipient",n.body().path("recipient"));
  store.jdbc().update("insert into cg_mailbox_capture(message_id,notice_id,branch_id,content_hash,envelope,accepted_at) values(?,?,?,?,?::jsonb,?)",UUID.fromString(capture.path("messageId").asString()),n.id(),n.branchId(),json.hash(capture),json.stringify(capture),Timestamp.from(clock.instant()));var body=(ObjectNode)n.body().deepCopy();body.put("state","DISPATCHED").set("dispatchAt",capture.path("acceptedAt"));var updated=notices.save(n,body,null,"DISPATCH",null);notices.event(updated,"LOCAL_CAPTURE",capture,null);notices.createDuty(updated,body);
 });}catch(Exception failure){tx.executeWithoutResult(status->{var n=notices.lock(job.targetId());if(!n.body().path("state").asString().equals("QUEUED")||!n.body().path("jobId").asString().equals(job.id().toString())){queue.cancel(job,"Notice source obsolete");return;}if(queue.fail(job,failure instanceof ApiException a?a.code():"STORAGE_INTEGRITY","Local dispatch could not commit")&&job.attempts()>=5){var b=(ObjectNode)n.body().deepCopy();b.put("state","FAILED");notices.save(n,b,null,"DISPATCH_FAILED",null);}});}}
 public void authorize(UUID id,Actor actor){notices.require(id,actor);actor.requireRole("MAKER","CHECKER");if(!actor.hasRole("CHECKER"))notices.maker(id,actor);}
 public void requireRetry(EntityStore.Entity job,Actor actor){var n=notices.require(id(job.body(),"parentId"),actor);authorize(n.id(),actor);if(!job.body().path("state").asString().equals("FAILED")||!n.body().path("state").asString().equals("IN_REVIEW")||n.body().hasNonNull("artifactId")||!n.body().path("artifactJobId").asString().equals(job.id().toString()))throw ApiException.of("STATE_CONFLICT","Notice PDF source is not retryable.");var s=notices.source(n);notices.sourceIntegrity(n,s);var expected=store.jdbc().queryForObject("select expected_hash from cg_job where id=?",String.class,job.id());if(!s.hash().equals(expected))throw ApiException.of("STORAGE_INTEGRITY","PDF expected source mismatch.");}
 public EntityStore.Entity retry(UUID id,String tag,String reason,Actor actor){var preview=store.require("Job",id);notices.lock(id(preview.body(),"parentId"));var job=store.lock("Job",id);ETags.check(tag,job.version());requireRetry(job,actor);if(!queue.retry(id))throw ApiException.of("STATE_CONFLICT","Job changed.");notices.event(store.require("Notice",id(preview.body(),"parentId")),"RETRY_ARTIFACT",json.object().put("reason",reason),actor);var updated=store.require("Job",id);audit.record(actor,"RETRY",updated,reason);return updated;}
}
